import { z } from 'zod';
import { objectIdSchema } from './pagination.js';
import type { UserSummaryDto } from './social.js';

export const MESSAGE_TEXT_MAX = 2_000;

export const openConversationSchema = z.object({ userId: objectIdSchema });
export type OpenConversationInput = z.infer<typeof openConversationSchema>;

export const sendMessageSchema = z.object({
  text: z.string().trim().min(1, 'Write a message').max(MESSAGE_TEXT_MAX),
  /**
   * Generated by the client per message. A retried send with the same id returns the original
   * message instead of posting it twice (flaky networks retry; users double-tap).
   */
  clientId: z.uuid(),
});
export type SendMessageInput = z.infer<typeof sendMessageSchema>;

export interface MessageDto {
  id: string;
  conversationId: string;
  senderId: string;
  text: string;
  clientId: string;
  createdAt: string;
}

export interface ConversationDto {
  id: string;
  /** The other participant (conversations are one-to-one). */
  user: UserSummaryDto;
  lastMessage: Pick<MessageDto, 'id' | 'senderId' | 'text' | 'createdAt'> | null;
  /** Messages the viewer hasn't read. */
  unread: number;
  /** When the other participant last read the conversation: drives "Seen". */
  otherLastReadAt: string | null;
  /** Whether the viewer may send (message policy and blocks); only on the single-conversation read. */
  canSend?: boolean;
}

export interface UnreadCountsDto {
  /** Conversations with unread messages. */
  messages: number;
  notifications: number;
}
